const items = $input.all();

const updatedItems = items.map((item) => {
  const link = item?.json?.links;

  if (typeof link === "string") {
    // Case: starts with "/" → already relative
    if (link.startsWith("/")) {
      item.json.links = link;
    } 

    // Case: absolute URL (http or https)
    else if (link.startsWith("http://") || link.startsWith("https://")) {
      try {
        const url = new URL(link);
        let path = url.pathname;

        // Strip trailing slash unless root "/"
        if (path !== "/" && path.endsWith("/")) {
          path = path.slice(0, -1);
        }

        item.json.links = path || "/";
      } catch (e) {
        // On parse error, keep original
        item.json.links = link;
      }
    }

    // Fallback: not relative or absolute, leave as-is
    else {
      item.json.links = link;
    }
  }

  return item;
});

return updatedItems;

const keywords = $('Set Config').item.json.target_keywords
  .split(',')
  .map(k => k.trim().toLowerCase());

const depriority = ['privacy', 'terms', 'login', 'sitemap', 'feed', 
  'careers', 'jobs', '#', 'mg_ld', 'linkedin', 'twitter', 
  'facebook', 'instagram', 'google', 'wp-'];

const scored = $input.all().map(item => {
  const link = (item.json.links || '').toLowerCase();
  const depth = link.split('/').filter(Boolean).length;
  const isDepriority = depriority.some(d => link.includes(d));
  const isPriority = keywords.some(k => link.includes(k));

  item.json._score = isDepriority ? -1 : isPriority ? 2 : depth === 1 ? 1 : 0;
  return item;
});

return scored.sort((a, b) => b.json._score - a.json._score);
